import { createHash } from 'crypto'
import { readFile, stat } from 'fs/promises'
import { fileURLToPath } from 'url'
import { z } from 'zod'
import type { TranscribedSegment, Transcriber } from './transcriber'

// The prepared demo lecture (demo/ at the repo root), generated by
// scripts/demo/make-lecture.sh. Its fixture holds the script text with exact
// per-paragraph timings and the wav's sha256, so mock mode can return the real
// transcript for the real audio: the demo's fallback if live transcription is
// unavailable.

// Resolved on use, not at import: under jsdom (the default test environment)
// import.meta.url is not a file URL, and importing deps.ts must not throw.
const demoFile = (name: string) => fileURLToPath(new URL(`../../../../demo/${name}`, import.meta.url))
export const demoLectureFixturePath = () => demoFile('lecture-mitochondrial-dna.segments.json')
export const demoLectureAudioPath = () => demoFile('lecture-mitochondrial-dna.wav')

const DEMO_SPEAKER = 'Lecturer'

const demoLectureSchema = z.object({
  audioFile: z.string(),
  audioSha256: z.string().regex(/^[0-9a-f]{64}$/),
  audioBytes: z.number().int().positive(),
  durationMs: z.number().int().positive(),
  voice: z.string(),
  segments: z
    .array(z.object({ startMs: z.number().int().nonnegative(), endMs: z.number().int().positive(), text: z.string().min(1) }))
    .min(1),
})

export type DemoLecture = z.infer<typeof demoLectureSchema>

export async function loadDemoLecture(fixturePath = demoLectureFixturePath()): Promise<DemoLecture> {
  return demoLectureSchema.parse(JSON.parse(await readFile(fixturePath, 'utf8')))
}

export function demoLectureSegments(lecture: DemoLecture): TranscribedSegment[] {
  return lecture.segments.map((s) => ({ ...s, speaker: DEMO_SPEAKER }))
}

async function sha256File(filePath: string): Promise<string> {
  return createHash('sha256').update(await readFile(filePath)).digest('hex')
}

interface DemoLectureCacheOptions {
  fixturePath?: string
  /** Matches the mock's "transcribing" pause; tests pass 0. */
  delayMs?: number
}

/**
 * Wraps the mock transcriber: an upload whose bytes hash to the demo wav gets
 * the real lecture script as segments; anything else falls through to
 * `fallback`. No network. A missing or unreadable fixture (e.g. a deploy that
 * does not ship demo/) logs once and falls through, so mock mode never breaks.
 */
export function withDemoLectureCache(fallback: Transcriber, options: DemoLectureCacheOptions = {}): Transcriber {
  const { fixturePath, delayMs = 0 } = options
  let lecture: Promise<DemoLecture | null> | undefined

  function getLecture(): Promise<DemoLecture | null> {
    lecture ??= loadDemoLecture(fixturePath ?? demoLectureFixturePath()).catch((err: Error) => {
      console.warn(`[transcribe] demo lecture cache disabled: ${err.message}`)
      return null
    })
    return lecture
  }

  return {
    name: fallback.name,
    async transcribe(audioFilePath) {
      const demo = await getLecture()
      // Size first, so ordinary uploads are never hashed. A missing file is
      // left to the fallback, which (as the mock) does not read it.
      const size = demo ? (await stat(audioFilePath).catch(() => null))?.size : undefined
      if (demo && size === demo.audioBytes && (await sha256File(audioFilePath)) === demo.audioSha256) {
        await new Promise((resolve) => setTimeout(resolve, delayMs))
        return demoLectureSegments(demo)
      }
      return fallback.transcribe(audioFilePath)
    },
  }
}
